% =====================================================================
\chapter{Der Mensch im Notfall: Psyche, Stress, Panik}
% =====================================================================

\section{Warum die Psyche zuerst kommt}

Jede Fertigkeit versagt, wenn die Hand zittert, das Blickfeld schrumpft und das Denken auf Flucht steht. Deshalb steht dieses Kapitel vor allen Technik-Kapiteln.

\begin{baustein}
\textbf{Merksatz.} Im Ernstfall versagt nicht das Werkzeug zuerst, sondern die Aufmerksamkeit. Atem und Uhr behalten, dann planen.
\end{baustein}

\begin{konzept}{2.1}{Stressreaktion erkennen und einordnen}
\textbf{Definition.} Eine Stressreaktion ist die k\"orperliche automatische Antwort auf Bedrohung: Puls, Atmung, Blickfeld und Denken ver\"andern sich messbar.

\textbf{Pr\"ufung.} (P1) Zwei unabh\"angige Quellen der Psychophysiologie (Lehrb\"ucher zur Stressreaktion, Erste-Hilfe-Leitlinien zur Akutbelastung). (P2) Symptomliste gegen Erste-Hilfe-Tabellen abgeglichen. (P3) Protokollierte Beobachtung bei drei \"Ubungen unter Zeitdruck (Vorlage A.3).

\textbf{Bewertung.} (B1) Nutzen: Wer die eigenen Symptome kennt, verwechselt Stress nicht mit t\"odlicher Gefahr. (B2) Aufwand: keine, nur Aufmerksamkeit. (B3) Ersatzl\"osung: ohne Einordnung folgt \"Uberreaktion oder L\"ahmung.

\textbf{Grenzen.} Starke Symptome k\"onnen auch Krankheit sein (Herz, Asthma, Unterzucker). \"Ortlich pr\"ufen: bei Brustschmerz mit Atemnot immer Hilfe suchen, auch ohne Strom.

\begin{longtable}{p{40mm}p{56mm}p{54mm}}
\caption{Tab. 2.1 -- Fr\"uhwarnzeichen der Stressreaktion}\\
\toprule
\textbf{Bereich} & \textbf{Zeichen} & \textbf{Gegenma\ss nahme}\\
\midrule
\endfirsthead
\toprule
\textbf{Bereich} & \textbf{Zeichen} & \textbf{Gegenma\ss nahme}\\
\midrule
\endhead
\bottomrule
\endfoot
K\"orper & Herzklopfen, kalte H\"ande, Zittern, trockener Mund & Atmung 4-4-4-4 (Tab. 2.2), 2 Minuten \\
Blick & Tunnelblick, \"Uberh\"oren von Ansprache & Blick bewusst 5 Objekte nacheinander benennen \\
Denken & Schwarz-Wei\ss -Denken, Handlungswiederholung & Ein Ziel laut aussprechen, dann 3 Schritte planen \\
Handeln & Weglaufen ohne Ziel oder Stillstand & STOP-Protokoll (Konzept 2.2) \\
\end{longtable}
\end{konzept}

\begin{konzept}{2.2}{STOP-Protokoll: die ersten 60 Sekunden}
\textbf{Definition.} STOP ist ein vier-Schritt-Selbstbefehl: Stoppen, Tief atmen, Orientieren, Planen.

\textbf{Pr\"ufung.} (P1) \"Ubliche Struktur aus Notfall- und Erste-Hilfe-Trainings (Stoppen, Atmen, Orientieren, Planen) in zwei unabh\"angigen Curricula. (P2) 60-Sekunden-Gliederung an Trainingszeiten gemessen. (P3) Dreimal unter provozierter Zeitnot ge\"ubt und protokolliert.

\textbf{Bewertung.} (B1) Nutzen: Unterbricht Panikketten in unter einer Minute. (B2) Aufwand: 1 Minute. (B3) Ersatzl\"osung: ersatzweise 10 tiefe Atemz\"uge und ein laut gesprochenes Ziel.

\textbf{Grenzen.} Bei akuter unmittelbarer Gefahr (Feuer im Raum, einst\"urzende Teile) erst k\"orperlich raus, dann STOP.

\textbf{Anleitung: STOP in 60 Sekunden.}
\begin{schritte}
\item Stoppe jede Bewegung. Steh oder sitz. Sprech laut: \glqq Stopp.\grqq
\item Atme viermal im Takt: 4 Sekunden ein, 4 halten, 4 aus, 4 halten.
\item Orientiere dich: nenne laut f\"unnf Dinge, die du siehst, und zwei, die du h\"orst.
\item Plane: sprich ein Ziel und drei Schritte dorthin. Beginne sofort mit Schritt 1.
\end{schritte}

